--@R6_DECLARATIONS@

begin

   ---------------------------------------------------------------------------------------
   -- Clocks: 50 MHz -> VCO 1200 MHz -> 162.71 / 100 / 200 MHz
   ---------------------------------------------------------------------------------------
   i_mmcm : MMCME2_BASE
      generic map (
         BANDWIDTH        => "OPTIMIZED",
         CLKIN1_PERIOD    => 20.0,
         DIVCLK_DIVIDE    => 1,
         CLKFBOUT_MULT_F  => 24.0,         -- 1200 MHz
         CLKOUT0_DIVIDE_F => 7.375,        -- 162.71 MHz  Rockchip bridge
         CLKOUT1_DIVIDE   => 12,           -- 100 MHz     M2M clk_i
         CLKOUT2_DIVIDE   => 6             -- 200 MHz     MIG system clock
      )
      port map (
         CLKIN1   => clk_in,
         CLKFBIN  => clk_fb_b,
         CLKFBOUT => clk_fb,
         CLKOUT0  => clk162_u,
         CLKOUT1  => clk100_u,
         CLKOUT2  => clk200_u,
         LOCKED   => mmcm_locked,
         PWRDWN   => '0',
         RST      => '0'
      );
   i_bufg_fb  : BUFG port map (I => clk_fb,   O => clk_fb_b);
   i_bufg_162 : BUFG port map (I => clk162_u, O => clk162);
   i_bufg_100 : BUFG port map (I => clk100_u, O => clk100);
   i_bufg_200 : BUFG port map (I => clk200_u, O => clk200);

   ---------------------------------------------------------------------------------------
   -- Reset: SW3 or the Rockchip (ctrl bit 0) holds the whole M2M system in reset
   ---------------------------------------------------------------------------------------
   process (clk100)
   begin
      if rising_edge(clk100) then
         reset_s     <= reset_s(1 downto 0) & (reset_button and mmcm_locked);
         sys_reset_n <= reset_s(2) and not rk_ctrl(0);
         heartbeat   <= heartbeat + 1;
      end if;
   end process;

   ---------------------------------------------------------------------------------------
   -- DDR3: MIG + Avalon bridge (both in ui_clk)
   ---------------------------------------------------------------------------------------
   process (clk_in)
   begin
      if rising_edge(clk_in) then
         if mmcm_locked = '0' then
            por_cnt       <= (others => '0');
            mig_sys_rst_n <= '0';
         elsif por_cnt /= x"FFFF" then
            por_cnt       <= por_cnt + 1;
            mig_sys_rst_n <= '0';
         else
            mig_sys_rst_n <= '1';
         end if;
      end if;
   end process;

   i_mig : mig_ddr3
      port map (
         ddr3_dq => ddr3_dq, ddr3_dqs_p => ddr3_dqs_p, ddr3_dqs_n => ddr3_dqs_n,
         ddr3_addr => ddr3_addr, ddr3_ba => ddr3_ba, ddr3_ras_n => ddr3_ras_n,
         ddr3_cas_n => ddr3_cas_n, ddr3_we_n => ddr3_we_n, ddr3_reset_n => ddr3_reset_n,
         ddr3_ck_p => ddr3_ck_p, ddr3_ck_n => ddr3_ck_n, ddr3_cke => ddr3_cke,
         ddr3_dm => ddr3_dm, ddr3_odt => ddr3_odt,
         app_addr => app_addr, app_cmd => app_cmd, app_en => app_en,
         app_wdf_data => app_wdf_data, app_wdf_end => app_wdf_end, app_wdf_mask => app_wdf_mask,
         app_wdf_wren => app_wdf_wren, app_rd_data => app_rd_data, app_rd_data_end => open,
         app_rd_data_valid => app_rd_data_valid, app_rdy => app_rdy, app_wdf_rdy => app_wdf_rdy,
         app_sr_req => '0', app_ref_req => '0', app_zq_req => '0',
         app_sr_active => open, app_ref_ack => open, app_zq_ack => open,
         ui_clk => mig_ui_clk, ui_clk_sync_rst => mig_ui_rst, init_calib_complete => mig_calib,
         sys_clk_i => clk200,
         device_temp_i => x"9F1",          -- ~40 C constant (no XADC reader in this design)
         sys_rst => mig_sys_rst_n
      );

   mem_not_ready <= mig_ui_rst or not mig_calib;

   -- test switch (stall controller register 0 bit 2): the old wiring, no burst abort on M2M resets
   process (mig_ui_clk)
   begin
      if rising_edge(mig_ui_clk) then
         mig_legacy_s <= mig_legacy_s(0) & stall_mode(2);
      end if;
   end process;
   mig_avm_rst <= hr_rst and not mig_legacy_s(1);

   i_avm_mig : entity work.avm_mig
      generic map (ADDR_BITS => 27)
      port map (
         clk => mig_ui_clk, rst => mem_not_ready,
         -- the framework's memory-side reset (every M2M reset): aborts a burst cleanly (avm_mig.vhd)
         avm_rst => mig_avm_rst, old_i => mig_legacy_s(1), dbg => mig_dbg,
         avm_write => mem_write, avm_read => mem_read, avm_address => mem_address,
         avm_writedata => mem_writedata, avm_byteenable => mem_byteenable,
         avm_burstcount => mem_burstcount, avm_readdata => mem_readdata,
         avm_readdatavalid => mem_readdatavalid, avm_waitrequest => mem_waitrequest,
         app_addr => c1_addr, app_cmd => c1_cmd, app_en => c1_en, app_rdy => c1_rdy,
         app_wdf_data => c1_wdata, app_wdf_end => c1_wend, app_wdf_wren => c1_wren,
         app_wdf_mask => c1_wmask, app_wdf_rdy => c1_wrdy, app_rd_data => c1_rdata,
         app_rd_data_valid => c1_rdv
      );

   -- the MIG's native UI shared by the line port (priority) and avm_mig (A1200 study C2)
   i_mig_arb : entity work.mig_arb
      port map (
         clk => mig_ui_clk, rst => mem_not_ready,
         lp_req => lp_req, lp_we => lp_we, lp_addr => lp_addr, lp_wdata => lp_wdata,
         lp_busy => lp_busy, lp_rvalid => lp_rvalid, lp_rdata => lp_rdata, lp_done => lp_done,
         c1_app_addr => c1_addr, c1_app_cmd => c1_cmd, c1_app_en => c1_en, c1_app_rdy => c1_rdy,
         c1_wdf_data => c1_wdata, c1_wdf_end => c1_wend, c1_wdf_wren => c1_wren,
         c1_wdf_mask => c1_wmask, c1_wdf_rdy => c1_wrdy, c1_rd_data => c1_rdata, c1_rd_valid => c1_rdv,
         app_addr => app_addr, app_cmd => app_cmd, app_en => app_en, app_rdy => app_rdy,
         app_wdf_data => app_wdf_data, app_wdf_end => app_wdf_end, app_wdf_wren => app_wdf_wren,
         app_wdf_mask => app_wdf_mask, app_wdf_rdy => app_wdf_rdy, app_rd_data => app_rd_data,
         app_rd_valid => app_rd_data_valid
      );

   -- line latency meter on the line port (stall monitor page 7, lat_meter.vhd)
   i_lat_meter : entity work.lat_meter
      generic map (G_FULL => G_LATMETER)
      port map (
         clk => mig_ui_clk, rst => mem_not_ready, cfg_i => rk_vid_sel,
         page7_o => lat_page7, aux_o => lat_aux, dbg_i => ad_dbg, mbox_i => amiga_mbox, pf_i => amiga_pf_stats,
         dbg2_i => amiga_fast_dbg,
         lp_req => lm_req, lp_we => lm_we, lp_addr => lm_addr, lp_wdata => lm_wdata,
         lp_busy => lm_busy, lp_done => lm_done
      );

   -- Avalon debug: mirror of avm_mig's write-burst bookkeeping, the last read burst, the time since
   -- the end of the last M2M memory reset (ui_clk ticks, saturating) at the start of the open write
   -- burst, and burst counts since that reset
   process (mig_ui_clk)
   begin
      if rising_edge(mig_ui_clk) then
         if ad_since /= x"FFFFFFFF" then ad_since <= ad_since + 1; end if;
         if mem_write = '1' and mem_waitrequest = '0' then
            if ad_wl = 0 then
               ad_waddr <= mem_address; ad_bc <= unsigned(mem_burstcount);
               ad_wl <= unsigned(mem_burstcount) - 1; ad_tw <= ad_since; ad_nw <= ad_nw + 1;
            else
               ad_wl <= ad_wl - 1;
            end if;
         end if;
         if mem_read = '1' and mem_waitrequest = '0' then
            ad_raddr <= mem_address; ad_rbc <= mem_burstcount; ad_nr <= ad_nr + 1;
         end if;
         if hr_rst = '1' then
            ad_since <= (others => '0'); ad_nw <= (others => '0'); ad_nr <= (others => '0');
            if mig_legacy_s(1) = '0' then ad_wl <= (others => '0'); end if;
         end if;
      end if;
   end process;
   ad_dbg <= std_logic_vector(ad_tw) & ad_raddr & std_logic_vector(ad_nw) & std_logic_vector(ad_nr) &
             mem_address & ad_waddr &
             std_logic_vector(ad_wl) & std_logic_vector(ad_bc) & mem_burstcount &
             mem_write & mem_read & mem_waitrequest & mig_avm_rst & mig_dbg(19 downto 16);

   -- line port mux: a request is held until the port is free; the chip cache goes first
   process (mig_ui_clk)
   begin
      if rising_edge(mig_ui_clk) then
         lp_req <= '0';
         if cc_req = '1' then lp_pend_c <= '1'; end if;
         if lm_req = '1' then lp_pend_m <= '1'; end if;
         if lp_done = '1' then lp_act <= '0'; end if;
         if lp_act = '0' and lp_busy = '0' and lp_req = '0' then
            if lp_pend_c = '1' or cc_req = '1' then
               lp_own_m <= '0'; lp_act <= '1'; lp_req <= '1'; lp_pend_c <= '0';
            elsif lp_pend_m = '1' or lm_req = '1' then
               lp_own_m <= '1'; lp_act <= '1'; lp_req <= '1'; lp_pend_m <= '0';
            end if;
         end if;
         if mem_not_ready = '1' then
            lp_pend_c <= '0'; lp_pend_m <= '0'; lp_act <= '0';
         end if;
      end if;
   end process;
   lp_we    <= lm_we    when lp_own_m = '1' else cc_we;
   lp_addr  <= lm_addr  when lp_own_m = '1' else cc_addr;
   lp_wdata <= lm_wdata when lp_own_m = '1' else cc_wdata;
   cc_busy  <= lp_pend_c or (lp_act and not lp_own_m);
   lm_busy  <= lp_pend_m or (lp_act and lp_own_m);
   cc_rvalid <= lp_rvalid and not lp_own_m;
   cc_done   <= lp_done and not lp_own_m;
   lm_done   <= lp_done and lp_own_m;
   diag_out <= lat_aux when lat_page7 = '1' else stall_diag;

   ---------------------------------------------------------------------------------------
   -- Rockchip bridge: SD sectors, key matrix, joysticks, QNICE UART
   ---------------------------------------------------------------------------------------
   i_rk_bridge : entity work.rk_bridge
      generic map (BIT_CLKS => 1412,       -- 162.71 MHz / 115200 baud (QNICE UART)
                   CORE_ID  => x"03",      -- Amiga (AExp)
                   HOST_FIFOS => G_LXSHELL)
      port map (
         clk => clk162, cpuclk => clk100,
         spi_sck => rk_sck, spi_cs_n => rk_cs_n, spi_mosi => rk_mosi, spi_miso => rk_miso,
         sd_rd_req => sd_rd_req, sd_wr_req => sd_wr_req, sd_lba => sd_lba, sd_seq => sd_seq,
         sd_inited => sd_inited, sd_cmd_cnt => sd_cmd_cnt, sd_last_cmd => sd_last_cmd,
         sd_rd_ready => sd_rd_ready, sd_rd_error => sd_rd_error, sd_wr_ack => sd_wr_ack,
         rbuf_addr => rbuf_addr, rbuf_data => rbuf_data,
         wbuf_we => wbuf_we, wbuf_addr => wbuf_addr, wbuf_data => wbuf_data,
         mon_rx => qnice_uart_rx, mon_tx => qnice_uart_tx,
         matrix_col_idx => kb_col_idx, matrix_col => kb_col,
         joya => rk_joya, joyb => rk_joyb, ctrl => rk_ctrl,
         pots => rk_pots,
         flash_active => open, flash_sck => fl_sck, flash_cs_n => fl_cs_n,
         flash_mosi => fl_mosi, flash_miso => fl_miso,
         iprog_toggle => ip_toggle, iprog_addr => ip_addr,
         video_sel => rk_vid_sel,
         video_diag => diag_out(95 downto 64), video_diag2 => diag_out(63 downto 0),
         host_clk => qnice_clk, host_s_data => host_s_data, host_s_valid => host_s_valid,
         host_s_pop => host_s_pop, host_m_data => host_m_data, host_m_push => host_m_push,
         host_m_full => host_m_full, host_clr => host_clr,
         host_ver => x"01" when G_LXSHELL else x"00", host_flags => host_flags,
         host_id => C_HOST_MENU_ID,
         spi_active => open
      );

   -- a1200-lxshell: no QNICE, no card for it: the emulated SD card is not built
   g_sd_emu : if not G_LXSHELL generate
   i_sd_emu : entity work.sd_emu
      generic map (SYNC_IN => true)        -- SimpleSDHC runs on its own 25 MHz clock
      port map (
         clk => clk100, sd_cs_n => sd_cs_n_s, sd_sclk => sd_sclk_s, sd_mosi => sd_mosi_s,
         sd_miso => sd_miso_s,
         rd_req => sd_rd_req, wr_req => sd_wr_req, req_lba => sd_lba, req_seq => sd_seq,
         rd_ready => sd_rd_ready, rd_error => sd_rd_error, wr_ack => sd_wr_ack,
         rbuf_addr => rbuf_addr, rbuf_data => rbuf_data,
         wbuf_we => wbuf_we, wbuf_addr => wbuf_addr, wbuf_data => wbuf_data,
         inited => sd_inited, cmd_count => sd_cmd_cnt, last_cmd => sd_last_cmd
      );
   end generate g_sd_emu;
   g_no_sd_emu : if G_LXSHELL generate
      sd_miso_s <= '1'; sd_rd_req <= '0'; sd_wr_req <= '0'; sd_lba <= (others => '0');
      sd_seq <= (others => '0'); rbuf_addr <= (others => '0'); wbuf_we <= '0';
      wbuf_addr <= (others => '0'); wbuf_data <= (others => '0'); sd_inited <= '0';
      sd_cmd_cnt <= (others => '0'); sd_last_cmd <= (others => '0');
   end generate g_no_sd_emu;

   caps_n <= not rk_ctrl(2);
   kb_up_n   <= not rk_ctrl(4);              -- INPUT ctrl b4 / b5: cursor up / left keys
   kb_left_n <= not rk_ctrl(5);
   rest_n <= not rk_ctrl(1);

   -- 100 MHz, as in phase 2.  m2m_keyb drives kio8 from the stoppable main_clk: a stall stretches a
   -- kio8 half period (1.6 us); the frame sync is ~42 us of kio8 high, so a 30 us threshold keeps
   -- stalls up to ~28 us from looking like a sync (the phase-2 value, 5 us, did not).  (Clocking the
   -- emulator and the mouse with main_clk instead broke Kickstart 3.1 boots in the stage-1 builds;
   -- cause not understood, see PORTING.md.)
   i_kbd_emu : entity work.m65kbd_emu
      generic map (SYNC_CYCLES => 3000)    -- 30 us at 100 MHz
      port map (
         clk => clk100, kio8 => kio8, kio10 => kio10,
         matrix_col_idx => kb_col_idx, matrix_col => kb_col,
         capslock_n => caps_n, restore_n => rest_n,
         up_n => kb_up_n, left_n => kb_left_n          -- cursor up / left keys
      );

   ---------------------------------------------------------------------------------------
   -- Configuration flash: x1 SPI through the Rockchip bridge (DQ0 = MOSI, DQ1 = MISO,
   -- DQ2 / DQ3 = WP# / HOLD# held high).  CCLK is the user clock of STARTUPE2.
   ---------------------------------------------------------------------------------------
   i_startup : STARTUPE2
      generic map (PROG_USR => "FALSE", SIM_CCLK_FREQ => 0.0)
      port map (CFGCLK => open, CFGMCLK => open, EOS => open, PREQ => open,
                CLK => '0', GSR => '0', GTS => '0', KEYCLEARB => '1', PACK => '0',
                USRCCLKO => fl_sck, USRCCLKTS => '0', USRDONEO => '1', USRDONETS => '1');
   qspi_csn   <= fl_cs_n;
   qspi_db(0) <= fl_mosi;
   qspi_db(1) <= 'Z';
   qspi_db(2) <= '1';
   qspi_db(3) <= '1';
   fl_miso    <= qspi_db(1);

   -- Rockchip command 0x60: warm boot into the bitstream at ip_addr (flash slot)
   i_iprog : entity work.rk_iprog
      port map (clk => clk100, iprog_toggle => ip_toggle, iprog_addr => ip_addr);

   -- Amiga mouse: counters from the Rockchip -> quadrature lines + buttons.  100 MHz as in phase 2,
   -- one transition per 20 us (was 1 us): a stall of the Amiga clock must not hide two steps from
   -- userio.v's 2-FF sampling (stalls up to ~19 us); 50,000 counts/s is still far above a USB mouse
   i_mouse : entity work.amiga_mouse
      generic map (STEP_CLKS => 2000)      -- 20 us per transition
      port map (clk => clk100, pots => rk_pots, port1_n => mouse1_n, port2_n => mouse2_n,
                core_pots => mouse_pots);

   -- the pot values (button levels) into the core's clock domain (upstream: the framework's
   -- paddle sampler CDC); the direction / fire lines are synchronised by M2M's debouncer
   process (main_clk)
   begin
      if rising_edge(main_clk) then
         pots_s1   <= mouse_pots;
         core_pots <= pots_s1;
      end if;
   end process;

   -- b0 up b1 down b2 left b3 right b4 fire; pad and mouse share a port like on the real DB9
   joya_n <= not rk_joya and mouse1_n;
   joyb_n <= not rk_joyb and mouse2_n;

   ---------------------------------------------------------------------------------------
   -- Unused MEGA65 ports of the core: idle levels
   ---------------------------------------------------------------------------------------
   cart_reset_in <= '1'; cart_game_in <= '1'; cart_exrom_in <= '1';
   cart_nmi_in   <= '1'; cart_irq_in  <= '1'; cart_roml_in  <= '1'; cart_romh_in <= '1';
   cart_ba_in    <= '1'; cart_rw_in   <= '1'; cart_io1_in   <= '1'; cart_io2_in  <= '1';
   cart_d_in     <= (others => '1');
   cart_a_in     <= (others => '1');

   led(0) <= mig_calib;
   led(1) <= main_drive_led;
   led(2) <= heartbeat(25);

   ---------------------------------------------------------------------------------------
   -- MiSTer2MEGA65 framework and the Amiga core (from top_mega65-r6.vhd, pins remapped)
   ---------------------------------------------------------------------------------------
--@FRAMEWORK@

--@CORE@

   -- a1200-ide: the hard disk pins (outputs only with G_HDD, the menu's IDE bit and, for MISO, CS)
   hd_sck_c  <= hd_sck  when G_HDD else '0';
   hd_mosi_c <= hd_mosi when G_HDD else '0';
   hd_cs_n_c <= hd_cs_n when G_HDD else '1';
   hd_miso   <= hd_miso_s when G_HDD and hd_miso_oe = '1' else 'Z';
   hd_att    <= hd_att_s  when G_HDD and hd_en = '1' else 'Z';

end architecture synthesis;
